'use strict';
const fs=require('node:fs');
const fsp=require('node:fs/promises');
const path=require('node:path');
const zlib=require('node:zlib');

// An Android native folder generated by Capacitor must already include a small
// Gradle Wrapper JAR. If it is missing/corrupt, restore the same asset from the
// installed @capacitor/cli template, not from an untrusted download URL.
const ENTRY='org/gradle/wrapper/GradleWrapperMain.class';
function jarContainsWrapperMain(buffer){
 if(!Buffer.isBuffer(buffer)||buffer.length<500||buffer.length>5*1024*1024)return false;
 if(buffer.readUInt32LE(0)!==0x04034b50)return false;
 // Inspect the ZIP central directory, not merely a string somewhere in bytes.
 // This also rejects a truncated or empty gradle-wrapper.jar.
 const min=Math.max(0,buffer.length-65557);
 for(let off=buffer.length-22;off>=min;off--){
  if(buffer.readUInt32LE(off)!==0x06054b50)continue;
  const count=buffer.readUInt16LE(off+10);
  const size=buffer.readUInt32LE(off+12);
  let cursor=buffer.readUInt32LE(off+16);
  if(!count||cursor+size>off)continue;
  for(let n=0;n<count;n++){
   if(cursor+46>off||buffer.readUInt32LE(cursor)!==0x02014b50)break;
   const filenameLength=buffer.readUInt16LE(cursor+28);
   const extraLength=buffer.readUInt16LE(cursor+30);
   const commentLength=buffer.readUInt16LE(cursor+32);
   if(cursor+46+filenameLength>off)break;
   const name=buffer.toString('utf8',cursor+46,cursor+46+filenameLength);
   if(name===ENTRY)return true;
   cursor+=46+filenameLength+extraLength+commentLength;
  }
  return false;
 }
 return false;
}
function jarIsUsable(file){
 try{return jarContainsWrapperMain(fs.readFileSync(file));}catch{return false;}
}
function templateEntry(archive,ending='gradle/wrapper/gradle-wrapper.jar'){
 if(!Buffer.isBuffer(archive)||archive.length<512||archive.length>90*1024*1024)throw new Error('Template Capacitor có kích thước không hợp lệ.');
 let offset=0;
 while(offset+512<=archive.length){
  const header=archive.subarray(offset,offset+512);
  if(header.every(b=>b===0))break;
  const name=header.subarray(0,100).toString('utf8').replace(/\0.*$/,'').replace(/\\/g,'/');
  const prefix=header.subarray(345,500).toString('utf8').replace(/\0.*$/,'');
  const rawSize=header.subarray(124,136).toString('ascii').replace(/\0.*$/,'').trim();
  if(!/^[0-7]+$/.test(rawSize))throw new Error('Template Capacitor chứa TAR header không hợp lệ.');
  const size=parseInt(rawSize,8);
  const start=offset+512, end=start+size;
  if(!Number.isFinite(size)||size<0||end>archive.length)throw new Error('Template Capacitor bị cắt hoặc hỏng.');
  const full=(prefix?prefix+'/':'')+name;
  if(full.endsWith(ending)&&!full.includes('../')&&(header[156]===0||header[156]===48)){
   const candidate=archive.subarray(start,end);
   if(!jarContainsWrapperMain(candidate))throw new Error('Gradle Wrapper trong template Capacitor bị lỗi.');
   return Buffer.from(candidate);
  }
  offset=start+Math.ceil(size/512)*512;
 }
 throw new Error('Template Capacitor không chứa gradle-wrapper.jar.');
}
function findCapacitorTemplate(projectRoot){
 const candidates=[
  path.join(projectRoot,'node_modules','@capacitor','cli','assets','android-template.tar.gz'),
  path.join(projectRoot,'node_modules','@capacitor','cli','dist','assets','android-template.tar.gz')
 ];
 return candidates.find(file=>fs.existsSync(file))||null;
}
async function ensureGradleWrapper(root,projectRoot,kind,{force=false,report=()=>{}}={}){
 const jar=path.join(root,'gradle','wrapper','gradle-wrapper.jar');
 if(!force&&jarIsUsable(jar))return {repaired:false,jar};
 if(kind!=='capacitor')throw new Error(
   'Gradle Wrapper JAR thiếu/hỏng: '+jar+'. Đây là dự án native; cần khôi phục wrapper chuẩn của dự án.'
 );
 const template=findCapacitorTemplate(projectRoot);
 if(!template)throw new Error(
   'Gradle Wrapper hỏng hoặc thiếu nhưng không tìm thấy @capacitor/cli/assets/android-template.tar.gz. '+
   'Cần cài lại thư viện Capacitor CLI của dự án, không phải Android SDK.'
 );
 report('Đang kiểm tra Gradle Wrapper trong bộ mẫu Capacitor...');
 const packed=await fsp.readFile(template);
 if(packed.length>25*1024*1024)throw new Error('Template Capacitor quá lớn, không thể khôi phục an toàn.');
 const archive=zlib.gunzipSync(packed,{maxOutputLength:90*1024*1024});
 const valid=templateEntry(archive);
 // Backup existing bytes once, then replace only the generated wrapper JAR.
 await fsp.mkdir(path.dirname(jar),{recursive:true});
 const backup=jar+'.baodroid-backup';
 if(fs.existsSync(jar)&&!fs.existsSync(backup))await fsp.copyFile(jar,backup);
 const temp=jar+'.baodroid-tmp-'+process.pid;
 try{
  await fsp.writeFile(temp,valid,{flag:'wx'});
  // On Windows, rename may not overwrite an existing target. The original is
  // already backed up; remove only the known malformed wrapper JAR.
  if(fs.existsSync(jar))await fsp.rm(jar);
  await fsp.rename(temp,jar);
 }finally{await fsp.rm(temp,{force:true}).catch(()=>{});}
 if(!jarIsUsable(jar))throw new Error('Không thể khôi phục Gradle Wrapper từ template.');
 report('Đã phục hồi Gradle Wrapper JAR từ Capacitor CLI (giữ backup file cũ).');
 return {repaired:true,jar};
}
module.exports={jarContainsWrapperMain,jarIsUsable,templateEntry,findCapacitorTemplate,ensureGradleWrapper};
